@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
  + IsFree : boolean
}

class Category {
  + Name : string
  + Price : double
}

class StayType {
  + Name : string
}

class Inhabitant {
  + Name : string
  + IdentificationData : string
  + AssessmentResult : string
}

class Registration {
  + RegistrationDate : date
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + Amount : double
  + PaymentDate : datetime
}

class Stay {
  + StartDate : date
  + IsSuspended : boolean
  + DiscountRate : double
}

enum StayTypeEnum {
  RH
  RNH
  SF
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
StayType "1" -- "1" Category
StayType "1" -- "1" StayTypeEnum

Inhabitant "1" -- "0..*" Stay
Inhabitant "1" -- "1" Registration
Inhabitant "1" -- "0..*" Proposal
Inhabitant "1" -- "0..*" Invoice

Stay "1" *-- "1" Bed
Stay "1" -- "1" StayType

Registration "1" -- "0..*" WaitingList
WaitingList "1" -- "1..*" Inhabitant

Proposal "1" -- "1" Inhabitant
Proposal "1" -- "1" StayType

Invoice "1" -- "1..*" Stay
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

